  const FIRST_NAMES = (typeof GERMAN_FIRST !== 'undefined' && GERMAN_FIRST.length) ? GERMAN_FIRST : ['Luca', 'Nico', 'Tim', 'Jan', 'Leon', 'Finn', 'Paul', 'Max', 'Elias', 'Noah', 'Ben', 'Jonas'];
