      const alle = grp ? grp.group.teams.map(function (t) { return t.ovr || 0; }).sort(function (a, b) { return b - a; }) : [];
      const mich = grp ? (grp.group.teams.filter(function (t) { return t.id === 'fcm'; })[0] || {}).ovr || 0 : 0;
      L.rang = alle.indexOf(mich) + 1;
